import { useState, useCallback, MouseEventHandler, ReactNode } from 'react';

export function useToggleButton() {
  const [pressed, setPressed] = useState(false);

  const getButtonProps = useCallback(
    (userProps?: { onClick?: MouseEventHandler<HTMLButtonElement> }) => ({
      'aria-pressed': pressed,
      onClick: (e: React.MouseEvent<HTMLButtonElement>) => {
        userProps?.onClick?.(e);
        if (!e.defaultPrevented) {
          setPressed((p) => !p);
        }
      },
    }),
    [pressed],
  );

  return { pressed, getButtonProps } as const;
}

export function ToggleButton({ children }: { children: ReactNode }) {
  const { pressed, getButtonProps } = useToggleButton();
  return <button {...getButtonProps()}>{pressed ? 'on' : 'off'} -- {children}</button>;
}
